'use strict';
function contextPrompts(){const p=project(),what={
 stats:[L("Wie lief meine Akquise?","How did my acquisition go?"),"stats"], fit:[L("Worauf stützt sich die Bewertung?","What supports this score?"),"fit"],cv:[L("Welche Referenzen gehören in den CV?","Which references belong in the CV?"),"cv"],follow:[L("Bei wem sollte ich nachhaken?","Who needs a follow-up?"),"follow"],capture:[L("Welche Felder soll ich prüfen?","Which fields should I review?"),"capture"],profile:[L("Wie belege ich meine Erfahrung?","How do I document my experience?"),"profile"],snap:[L("Welche Fassung habe ich verschickt?","Which version did I send?"),"snap"],apply:[L("Wie vermerke ich die Bewerbung?","How do I record this application?"),"apply"]};
const choices={home:["fit","cv","follow"],dashboard:["follow","snap","fit"],progress:["stats","follow"],opportunities:["follow","capture","fit"],archived:["snap","follow"],capture:["capture","profile"],manual:["capture","profile"],experience:["profile","cv"],import:["profile","cv"],fit:["fit","cv","profile"],cv:["cv","fit"],email:["apply","cv"],portal:["apply","snap"],application:["snap","follow"],snapshot:["snap","cv"],note:["follow","snap"]};
return (choices[S.view]||choices.home).map(k=>what[k])}
function demoAnswer(intent){const p=project(),rows=p?assess(p):[],full=rows.filter(a=>a[3]==="full"),open=rows.filter(a=>a[3]!=="full"),s=p&&S.snapshots[p.id];
 if(intent==="stats")return [progressBrief(),"progress"];
 if(intent==="brief"){if(S.view==="progress")return [progressBrief(),"progress"];if(S.view==="dashboard"||S.view==="opportunities")return demoAnswer("follow");return demoAnswer(contextPrompts()[0][1])}
 if(intent==="fit")return [p?`${p.title} · ${getScore(rows)??"–"}/10. ${L("Belegt","Supported")}: ${full.map(r=>r[0]+" ("+r[2]+")").join(", ")||"–"}. ${L("Zu klären","To clarify")}: ${open.map(r=>r[0]).join(", ")||"–"}.`:L("Erfasse ein Projekt für den Abgleich.","Capture a project to review fit."),"fit"];
 if(intent==="cv"){const ids=[...new Set(full.map(r=>r[2]))];const sources=S.refs.filter(r=>ids.includes(r.id));return [sources.length?L("Für dieses Projekt passen ","For this opportunity I would use ")+sources.map(r=>r.org+" ("+r.id+")").join(", ")+". "+L("Im Entwurf kannst du die Auswahl und den Wortlaut prüfen.","Review the references and wording in the draft."):L("Hinterlege zuerst die persönlichen Beiträge, die diese Anforderungen belegen.","Add your contributions that support the requirements first."),"cv"]}
 if(intent==="follow"){const due=S.projects.filter(x=>!x.archived&&x.channel&&x.status!=="closed"&&x.due&&x.due<=demoDay).sort((a,b)=>a.due.localeCompare(b.due));return [due.length?due.map(x=>`${x.company} · ${x.contact||x.title} · ${formatDate(x.due)}`).join("\n"):L("Alle Wiedervorlagen in der Beispieldemo sind erledigt.","All follow-ups in the example are complete."),"dashboard"]}
 if(intent==="snap")return [s?`${s.project.company} · ${formatDate(s.when,true)} · ${s.channel==="portal"?"Portal":"E-Mail"}. ${s.fileName||L("Kein CV hinterlegt.","No CV attached.")} ${L("Die damaligen Belege findest du in der versendeten Fassung.","See the submission snapshot for the evidence used at the time.")}`:L("Für dieses Projekt wurde noch keine Bewerbung vermerkt.","No submission has been recorded for this project."),s?"snapshot":"email"];
 if(intent==="apply")return [L("Du kannst den Beispielversand per E-Mail bestätigen oder den tatsächlichen Zeitpunkt im Portal festhalten. Der ausgewählte CV wird mit seiner damaligen Fassung gespeichert.","Confirm the example email delivery or record when you applied on the portal. The selected CV is saved with that submission."),S.view==="portal"?"portal":"email"];
 if(intent==="profile")return [L("Erfasse für jede Referenz Zeitraum, Rolle und deinen eigenen Beitrag. Juniper Health belegt den Offline-Check-in. Kite Transit belegt praktische TalkBack-Tests.","Record the dates, role and your own contribution. Juniper Health supports offline check-in. Kite Transit supports hands-on TalkBack testing."),"experience"];
 return [L("Prüfe Endkunde und Vermittlung getrennt. Übernimm Pflichtanforderungen und Wünsche aus der Ausschreibung. Bei einem geschützten Portal kannst du den sichtbaren Text einfügen.","Check the end client and agency separately. Review the required and preferred experience. For a gated portal, paste the visible listing text."),"capture"]}
async function detectLocal(){if(!["localhost","127.0.0.1","[::1]"].includes(location.hostname)||!/^https?:$/.test(location.protocol))return;try{const r=await fetch("./api/assma/status",{headers:{Accept:"application/json"}});if(!r.ok||!r.headers.get("content-type")?.includes("application/json"))return;const d=await r.json();dictation.localWhisper=d.voice===true;if(d.local&&d.model){S.localModel=d.model;renderAssistant()}}catch{}}
function classify(q){const val=normal(q);for(const [id,re] of [["stats",/statistik|fortschritt|progress|wie lief|acquisition go/],["brief",/briefing/],["snap",/snapshot|fassung|version|sent|verschickt|original/],["cv",/\bcv\b|lebenslauf|resume|referenz|reference/],["follow",/nachhak|fällig|follow|due|nachfass|wiedervorlage/],["profile",/profil|erfahrung erfass|meinen beitrag/],["capture",/feld|link|url|erfass|listing|capture/],["apply",/portal|email|mail|bewerben|apply/],["fit",/pass|fit|st[räa]+k|anforder|score|bewert|evidence|gap|fhir|kotlin/]]){if(re.test(val))return id}return null}
async function ask(q,intent){if(S.chatBusy||!q.trim())return;cancelDictation();dock.writing=false;dock.history=false;S.chatOpen=true;const req=++S.assistantRequest;const controller=new AbortController();dock.request=controller;const p=project();S.chat.push({who:"user",text:q});S.chatBusy=true;renderAssistant();let answer,to;
try{if(S.localModel){const ctx={screen:S.view,period:S.view==="progress"?progressBrief():undefined,project:p?{title:p.title,company:p.company,requirements:assess(p),followUp:p.due,channel:p.channel}:null,evidence:S.refs.map(r=>({id:r.id,org:r.org,role:r.role,years:r.years,contribution:T(r.body)})),snapshot:p&&S.snapshots[p.id]?{date:S.snapshots[p.id].when,filename:S.snapshots[p.id].fileName}:null};const r=await fetch("./api/assma/chat",{method:"POST",signal:controller.signal,headers:{"Content-Type":"application/json"},body:JSON.stringify({question:q,context:ctx,language:S.lang})});const result=await r.json();if(!r.ok||!result.answer)throw Error("local");answer=result.answer}else{const matched=intent||classify(q);if(matched)[answer,to]=demoAnswer(matched);else answer=L("Im Beispiel kann ich die Passung erklären, Referenzen für den CV nennen und Wiedervorlagen zeigen. Wähle eines dieser Themen. In deiner lokalen Installation kann ein verbundenes Ollama-Modell freie Fragen beantworten.","In this example I can explain fit, suggest CV references and show due follow-ups. Pick a topic. A connected Ollama model in your local installation can answer free-form questions.")}}catch{answer=L("Das lokale Modell hat nicht geantwortet. Prüfe, ob Ollama läuft, und versuche es noch einmal.","The local model did not respond. Check that Ollama is running and try again.")}
if(req!==S.assistantRequest)return;S.chat.push({who:"assistant",text:answer,to});S.chat=S.chat.slice(-12);S.chatBusy=false;dock.request=null;renderAssistant();readReply(answer)}

